/**
 * `akm rules`: the rules that apply here, in full. Read from the files of the
 * bundles the selection names (never the index), recognized by the same adapter
 * and filtered by the same project and scope functions search uses, so it works
 * with no index and a new rule applies at once. Records one `rules` usage event.
 */
import path from "node:path";
import { getStringArg, PROJECT_ARG } from "../../cli/parse-args.js";
import { defineJsonCommand, output, parseAllFlagValues } from "../../cli/shared.js";
import { akmAdapter } from "../../core/adapter/adapters/akm-adapter.js";
import { parseFrontmatter } from "../../core/asset/frontmatter.js";
import { displayRefForConceptId } from "../../core/asset/resolve-ref.js";
import { compareCodePoints } from "../../core/common.js";
import { loadConfig } from "../../core/config/config.js";
import { resolveProject } from "../../core/projects.js";
import { withStateDbTelemetry } from "../../core/state-db.js";
import { warnOnce } from "../../core/warn.js";
import { deriveInstallations } from "../../indexer/installations.js";
import { isProposedQuality, scopeMatchesFilters } from "../../indexer/passes/metadata.js";
import { resolveReadSources } from "../../indexer/read-preflight.js";
import { drainDirDocuments } from "../../indexer/scan/drain-dir.js";
import { appliesUnder } from "../../indexer/search/db-search.js";
import { insertUsageEvent, resolveUsageEventSource } from "../../indexer/usage/usage-events.js";
import { buildFileContext } from "../../indexer/walk/file-context.js";
import { walkedFiles, walkStash } from "../../indexer/walk/walker.js";
import { registerMdRenderer } from "../../output/render-registry.js";
import { formatRulesText } from "../../output/text/rules.js";
import { TELEMETRY_BUSY_TIMEOUT_MS } from "../../storage/repositories/index-db.js";
import { assertNamedSourceExists, narrowSourcesToName, normalizeScopeFilters, parseScopeFilterFlags, parseSearchSource, } from "./search.js";
import { fromValues, projectContext, scopeFilterArg, stampedProject, withProjectDefaults } from "./search-cli.js";
/** `--from` values that select a search scope, not a bundle: they do not apply to rules. */
const SCOPE_KEYWORDS = ["local", "registry", "all"];
/** The bundle names in a `--from` value; scope keywords are ignored with one warning. `undefined`: none left. */
function bundleNames(from) {
    if (from === undefined)
        return undefined;
    const parsed = parseSearchSource(from);
    const given = Array.isArray(parsed) ? parsed : [parsed];
    const names = given.filter((name) => !SCOPE_KEYWORDS.includes(name));
    if (names.length < given.length) {
        warnOnce("rules:from-keyword", "`akm rules` reads named bundles: --from local, registry and all are ignored.");
    }
    return names.length > 0 ? names : undefined;
}
export function akmRules(input) {
    const config = loadConfig();
    const project = resolveProject(config, { project: input.project, cwd: input.cwd });
    const { filters, view } = withProjectDefaults(project, {
        source: input.from,
        filters: parseScopeFilterFlags(input.filters ?? [], "--filter"),
    });
    const names = bundleNames(input.from) ?? bundleNames(project?.from);
    for (const name of names ?? [])
        assertNamedSourceExists(config, name);
    const sources = resolveReadSources(undefined, config).sources;
    const wanted = names
        ? names.flatMap((name) => narrowSourcesToName(sources, [name]))
        : [
            ...sources.filter((source) => source.isDefault),
            ...(project?.write.bundle ? narrowSourcesToName(sources, [project.write.bundle]) : []),
        ];
    const installations = deriveInstallations(sources);
    const scope = normalizeScopeFilters(filters);
    const context = projectContext(project, filters);
    const bundles = [];
    const found = [];
    for (const source of new Set(wanted)) {
        const component = installations[sources.indexOf(source)]?.components[0];
        if (!component || component.adapter !== "akm" || source.unresolved)
            continue;
        bundles.push(component.id);
        const files = walkedFiles(component.root, walkStash(path.join(component.root, "rules"), "rule").flatMap((group) => group.files));
        for (const file of files) {
            const ctx = buildFileContext(component.root, file);
            const drained = drainDirDocuments(akmAdapter, component, [ctx]);
            const entry = drained.entries[0];
            const conceptId = drained.conceptIdByFile.get(ctx.absPath);
            if (entry?.type !== "rule" || conceptId === undefined)
                continue;
            if (isProposedQuality(entry.quality) || !appliesUnder(entry, context))
                continue;
            if (scope && !scopeMatchesFilters(entry, scope))
                continue;
            const named = entry.frontmatter?.project;
            found.push({
                ref: displayRefForConceptId(conceptId, component.id, config.defaultBundle ?? (source.isDefault ? component.id : undefined)),
                durableRef: `${component.id}//${conceptId}`,
                ...(entry.description ? { description: entry.description } : {}),
                ...(named?.length ? { project: named.length === 1 ? named[0] : named } : {}),
                content: parseFrontmatter(ctx.content()).content.trim(),
                shared: !named?.length,
            });
        }
    }
    found.sort((a, b) => Number(a.shared) - Number(b.shared) || compareCodePoints(a.ref, b.ref));
    const rules = found.map(({ shared: _shared, durableRef: _durableRef, ...rule }) => rule);
    recordRulesUsage({
        project: stampedProject(project),
        bundles,
        refs: found.map((rule) => rule.durableRef),
        chars: found.reduce((sum, rule) => sum + rule.content.length, 0),
        eventSource: input.eventSource ?? resolveUsageEventSource(),
    });
    return { schemaVersion: 1, ...(view ? { project: view } : {}), bundles, rules };
}
/** One `rules` usage event per call: what was loaded, not a search or a show. */
function recordRulesUsage(load) {
    const { eventSource, ...metadata } = load;
    try {
        withStateDbTelemetry((stateDb) => {
            insertUsageEvent(stateDb, { event_type: "rules", metadata: JSON.stringify(metadata), source: eventSource });
        }, TELEMETRY_BUSY_TIMEOUT_MS);
    }
    catch {
        /* telemetry is fire-and-forget */
    }
}
export const rulesCommand = defineJsonCommand({
    meta: {
        name: "rules",
        description: "The rules that apply here, in full: the project's and the shared ones, read from the files of the project's bundles (its `from`, else the default bundle and its write bundle)",
    },
    args: {
        from: {
            type: "string",
            description: "Bundle name (repeatable); default: the project's from, else the default bundle",
        },
        filter: scopeFilterArg,
        ...PROJECT_ARG,
    },
    async run({ args }) {
        output("rules", akmRules({
            from: fromValues(args.from),
            filters: parseAllFlagValues("--filter"),
            project: getStringArg(args, "project"),
        }));
    },
});
registerMdRenderer("rules", (result) => formatRulesText(result));
